  const url = new URL(route.request().url())
  if (url.pathname === "/api/v1/host") return json(route, { hostId: "local-host", capabilities: [] })
  if (url.pathname.endsWith("/snapshot")) return json(route, { sessionId: "session-1", lastEventSeq: 1, running: false })
  if (url.pathname.endsWith("/timeline")) return json(route, { items: [{ id: "message-1", key: "message-1", sequence: 1, role: "assistant", text: "restored after browser restart", toolCalls: [] }], olderCursor: "", newerCursor: "" })
  if (url.pathname.endsWith("/composer")) return json(route, { configRevision: 0, profileRevision: 0, profileId: "faux", modelId: "faux-1", reasoning: "default", permissionMode: "ask" })
  if (url.pathname.endsWith("/queue")) return json(route, { queueRevision: 0, paused: false, items: [] })
  if (url.pathname === "/api/v1/provider-profiles") return json(route, { profiles: [{ profileId: "faux", revision: 0, family: "openai-compatible", baseUrl: "https://provider.invalid", credential: { credentialId: "none", type: "none" }, headerCredentials: {}, models: [{ modelId: "faux-1", displayName: "Faux 1", capabilities: ["text"], settings: {} }], defaultModel: "faux-1", settings: {} }] })
